/**风险指标: 商品及金融衍生品类理财产品投资于商品及金融衍生品的比例不低于80% **/

DELETE FROM RSK_ISUP_INDICATOR WHERE IND_ID='73cfb1263c5b4fbfa1003f045718b22f';
INSERT INTO RSK_ISUP_INDICATOR (IND_ID, IND_NAME, IND_TYPE, EXPR, SUP_TYPE, TIME_POINT, SUP_FREQUENCY, SUP_DIRECTION, WARN_COND, APPROVE_COND, FOUL_COND, IS_ADJUST, ADJUST, IS_ENABLED, MEMO, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_EXCP_WHEN_DIV_ZERO, COMPARE_DAYS, INSTITUTION_CODE, SUP_DISPLAY_CLASSIFY, ASSET_THR_TYPE, INVEST_PROPORTY, IS_DISPLAY_ORIGINAL,SUP_DOC,IND_NUM)
VALUES('73cfb1263c5b4fbfa1003f045718b22f','商品及金融衍生品类理财产品投资于商品及金融衍生品的比例不低于80%','LIMIT_INVEST','${SPJJRYSPLZCGM}/${CPZZC}','SUPERVISION','01,02,03','DAYTIME,DAYEND', null , '{"threshold_1":{"op":"<","unit":"PERCENT","is_model":"02"}}' , '{"threshold_1":{"op":"<","unit":"PERCENT","is_model":"02"}}'  , '{"threshold_1":{"op":"<","value":"80.0000","unit":"PERCENT","is_model":"02"}}' , 'N' , null , '01' , null ,'system',null,sysdate,'system',sysdate, '03' , null , null , null  , null , null  , 'Y' , '《商业银行理财业务监督管理办法》第9条  商业银行应当根据投资性质的不同，将理财产品分为固定收益类理财产品、权益类理财产品、商品及金融衍生品类理财产品和混合类理财产品。固定收益类理财产品投资于存款、债券等债权类资产的比例不低于80%；权益类理财产品投资于权益类资产的比例不低于80%；商品及金融衍生品类理财产品投资于商品及金融衍生品的比例不低于80%；混合类理财产品投资于债权类资产、权益类资产、商品及金融衍生品类资产且任一资产的投资比例未达到前三类理财产品标准。  非因商业银行主观因素导致突破前述比例限制的，商业银行应当在流动性受限资产可出售、可转让或者恢复交易的15个交易日内将理财产品投资比例' , 'SUP080070' );
